#include "frontier.h"
#include "standard.h"

#include "memory.h"
#include "strings.h"
#include "lang.h"
#include "langinternal.h"
#include "tablestructure.h"

/* Token enum for all verbs in the webserver processor */
enum {
    webv_server = 0,
    webv_dispatch = 1,
    webv_parseheaders = 2,
    webv_parsecookies = 3,
    webv_buildresponse = 4,
    webv_builderrorpage = 5,
    webv_getserverstring = 6
};

static boolean webserver_valueproc(short token, hdltreenode hparam1,
                                     tyvaluerecord *vreturned,
                                     bigstring bserror) {
    switch(token) {
        case webv_server:
            /* Verb #0: webserver.server - @SCRIPT_IMPLEMENTED (pure UserTalk) */
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        case webv_dispatch:
            /* Verb #1: webserver.dispatch - @SCRIPT_IMPLEMENTED (pure UserTalk) */
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        case webv_parseheaders:
            /* Verb #2: webserver.parseheaders - @SCRIPT_IMPLEMENTED (pure UserTalk) */
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        case webv_parsecookies:
            /* Verb #3: webserver.parsecookies - @SCRIPT_IMPLEMENTED (pure UserTalk) */
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        case webv_buildresponse:
            /* Verb #4: webserver.buildresponse - @SCRIPT_IMPLEMENTED (pure UserTalk) */
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        case webv_builderrorpage:
            /* Verb #5: webserver.builderrorpage - @SCRIPT_IMPLEMENTED (pure UserTalk) */
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        case webv_getserverstring:
            /* Verb #6: webserver.getserverstring - @SCRIPT_IMPLEMENTED (pure UserTalk) */
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        default:
            return false;
    }
}

boolean webserverinitverbs(void) {
    hdlhashtable htable = nil;
    bigstring bsname;

    copystring(BIGSTRING("\pwebserver"), bsname);

    if (!newfunctionprocessor(bsname, &webserver_valueproc, false, &htable))
        return false;

    pushhashtable(htable);

    #define ADD_VERB(name, tok) do { \
        bigstring bs; \
        copystring(name, bs); \
        if (!langaddkeyword(bs, tok)) { \
            pophashtable(); \
            return false; \
        } \
    } while(0)

    ADD_VERB(BIGSTRING("\pserver"), webv_server);
    ADD_VERB(BIGSTRING("\pdispatch"), webv_dispatch);
    ADD_VERB(BIGSTRING("\pparseheaders"), webv_parseheaders);
    ADD_VERB(BIGSTRING("\pparsecookies"), webv_parsecookies);
    ADD_VERB(BIGSTRING("\pbuildresponse"), webv_buildresponse);
    ADD_VERB(BIGSTRING("\pbuilderrorpage"), webv_builderrorpage);
    ADD_VERB(BIGSTRING("\pgetserverstring"), webv_getserverstring);

    #undef ADD_VERB

    pophashtable();
    return true;
}
